/**
 * A table that allow users to provide a list of data objects whose method can be used
 * to create columns.
 *
 * @param <T> the row object type
 */
public class AnyObjectTableModel<T> : GDynamicColumnTableModel<T, object> {
	private List<T> data;
	private string name;

	public AnyObjectTableModel(string modelName, Class<T> dataClass, params string[] methodNames) : this(modelName, new List<T>(), dataClass, Arrays.asList(methodNames))
    {
	}

	public AnyObjectTableModel(string modelName, params Method[] methods) : this(modelName, new List<T>(), Arrays.asList(methods))
    {
	}

	public AnyObjectTableModel(string modelName, List<Method> methods) : this(modelName, new List<T>(), methods)
    {
	}

	public AnyObjectTableModel(string modelName, Class<T> dataClass, List<string> methodNames) : this(modelName, new List<T>(), dataClass, methodNames)
    {
	}

	public AnyObjectTableModel(string modelName, List<T> data, Class<T> dataClass,
			List<string> methodNames) : base(new ServiceProviderStub())
    {
		this.data = data;
		this.name = modelName;

		Objects.requireNonNull(methodNames);
		SystemUtilities.assertTrue(!methodNames.isEmpty(), "Method names must be provided");

		foreach (string methodName in methodNames) {
			addTableColumn(new MethodColumn(dataClass, methodName));
		}
	}

	public AnyObjectTableModel(string modelName, List<T> data, List<Method> methods) : base(new ServiceProviderStub())
    {
		this.data = data;
		this.name = modelName;

		Objects.requireNonNull(methods);
		SystemUtilities.assertTrue(!methods.isEmpty(), "Methods must be provided");

		foreach (Method method in methods) {
			addTableColumn(new MethodColumn(method));
		}
	}

	/* @Override */
	public string getName() {
		return name;
	}

	/* @Override */
	public bool isSortable(int columnIndex) {
		return true;
	}

	/* @Override */
	public List<T> getModelData() {
		return data;
	}

	public void setModelData(List<T> data) {
		this.data = data;
		fireTableDataChanged();
	}

	/* @Override */
	protected TableColumnDescriptor<T> createTableColumnDescriptor() {
		return new();
	}

	/* @Override */
	public object getDataSource() {
		return null;
	}

	private static string fromCamelCase(string text) {
		StringBuilder buffy = new StringBuilder();

		//@formatter:off
		text.chars()
			.mapToObj(i => (char) i)
			.forEach(c => {
				if (c == '_') {
					buffy.append(' ');
				}
				else if (Character.isUpperCase(c)) {
					if (buffy.length() > 1) { // no space in the front
						buffy.append(' ');
					}
					buffy.append(c);
				}
				else {
					bool wasSpace = isLastCharASpace(buffy);
					char C = maybeToUpperCase(c, wasSpace);
					buffy.append(C);
				}

			})
			;
		//@formatter:on

		buffy.replace(0, 1, buffy.substring(0, 1).toUpperCase()); // Initial cap

		return buffy.toString();
	}

	private static bool isLastCharASpace(StringBuilder buffy) {
		if (buffy.length() == 0) {
			return false;
		}
		return buffy.charAt(buffy.length() - 1) == ' ';
	}

	private static char maybeToUpperCase(char c, bool shouldBeUpper) {

		if (shouldBeUpper) {
			return Character.toUpperCase(c);
		}

		return c;
	}

	private class MethodColumn : AbstractDynamicTableColumn<T, object, object> {
		private string methodName;
		private Method method;
		private Class<object> returnType;

		public MethodColumn(Class<T> dataClass, string methodName) {
			try {
				Method m = dataClass.getMethod(methodName);
				init(m);
			}
			catch (Exception e) when (e is NoSuchMethodException or SecurityException) {
				this.methodName = "No method: " + methodName;
			}
		}

		public MethodColumn(Method method) {
			init(method);
		}

		/* @Override */
		public string getColumnDescription() {
			return null;
		}

		private void init(Method m) {
			this.method = m;
			methodName = method.getName();
			if (methodName.startsWith("get")) {
				methodName = methodName.substring(3);
			}

			methodName = fromCamelCase(methodName);
			returnType = method.getReturnType();
		}

		/* @SuppressWarnings("unchecked") */
		/* @Override */
		public Class<object> getColumnClass() {
			return (Class<object>) returnType;
		}

		/* @Override */
		public string getColumnName() {
			return methodName;
		}

		/* @Override */
		public object getValue(T rowObject, Settings settings, object dataSource,
				ServiceProvider sp)
    {
			if (method == null) {
				Msg.error(this, "No method '" + methodName + "' on class " +
					rowObject.GetType().getSimpleName());
				return null;
			}
			try {
				return method.invoke(rowObject);
			}
			catch (Exception e) when (e is IllegalAccessException or IllegalArgumentException or InvocationTargetException) {
				Msg.debug(this, "Problem invoking method: " + method.getName() + " on " +
					method.getDeclaringClass().getSimpleName() + ". See nested exception", e);
			}
			return null;
		}

	}

}
